245	    @Override
246	    @Transactional
247	    public void saveOwner(Owner owner) throws DataAccessException {
248	        if (owner.getTelephone() != null) {
249	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
250	        }
251	        if (owner.getEmail() != null) {
252	            owner.setEmail(normalizeEmail(owner.getEmail()));
253	        }
254	        if (owner.getAddress() != null) {
255	            owner.setAddress(normalizeAddress(owner.getAddress()));
256	        }
257	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
258	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
259	        if (owner.getCustomerCode() == null) {
260	            owner.setCustomerCode(generateCustomerCode(owner));
261	        }
262	        boolean creating = owner.isNew();
263	        if (creating) {
264	            owner.setNamesakeCount(countNamesakes(owner));
265	            assertDailyCapacity(owner);
266	            assertCityCapacity(owner);
267	        }
268	        assertTelephoneUnique(owner, owner.getTelephone());
269	        List<Owner> household = findHouseholdMembers(owner);
270	        assertHouseholdAllowed(owner, household);
271	        assignHousehold(owner, household);
272	        ownerRepository.save(owner);
273	        if (creating) {
274	            AUDIT.info("owner created: id={} customerCode={} registrationDate={}",
275	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
276	        }
277	    }
278	
279	    /**
280	     * Build a {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
281	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
282	     * letters of {@code lastName}, and NNNN is a per-city 4-digit zero-padded sequence equal to
283	     * one more than the number of owners already in that city.
284	     */
285	    private String generateCustomerCode(Owner owner) {
286	        String cityPrefix = prefix3(owner.getCity());
287	        String lastNamePrefix = prefix3(owner.getLastName());
288	        long sequence = countOwnersInCity(owner.getCity()) + 1L;
289	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
290	    }
291	
292	    private static String prefix3(String value) {
293	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
294	    }
295	
296	    /** Maximum number of owners permitted in a single city. */
297	    private static final long CITY_OWNER_LIMIT = 50L;
298	
299	    /**
300	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
301	     * more owners, so no city can grow beyond the capacity limit.
302	     *
303	     * @throws CityOwnerLimitException if the owner's city is already at capacity
304	     */
305	    private void assertCityCapacity(Owner owner) {
306	        if (owner.getCity() == null) {
307	            return;
308	        }
309	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
310	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
311	        }
312	    }
313	
314	    /**
315	     * Rolls {@code date} forward to the next business day when it falls on a weekend: a Saturday or
316	     * Sunday becomes the following Monday. Business days (Monday to Friday) are returned unchanged.
317	     */
318	    private static LocalDate rollToBusinessDay(LocalDate date) {
319	        switch (date.getDayOfWeek()) {
320	            case SATURDAY:
321	                return date.plusDays(2);
322	            case SUNDAY:
323	                return date.plusDays(1);
324	            default:
325	                return date;
326	        }
327	    }
328	
329	    /** Maximum number of owners permitted to be registered on a single day. */
330	    private static final long DAILY_OWNER_LIMIT = 100L;
331	
332	    /**
333	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
334	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
335	     * many owners can be created on any single day.
336	     *
337	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
338	     */
339	    private void assertDailyCapacity(Owner owner) {
340	        LocalDate date = owner.getRegistrationDate();
341	        if (date == null) {
342	            return;
343	        }
344	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
345	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
346	        }
347	    }
348	
349	    private long countOwnersRegisteredOn(LocalDate date) {
350	        return ownerRepository.findAll().stream()
351	                .filter(existing -> date.equals(existing.getRegistrationDate()))
352	                .count();
353	    }
354	
355	    private long countOwnersInCity(String city) {
356	        String normalized = normalizeHouseholdValue(city);
357	        return ownerRepository.findAll().stream()
358	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
359	                .count();
360	    }
361	
362	    /**
363	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
364	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
365	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
366	     * that already existed before this create.
367	     */
368	    private int countNamesakes(Owner owner) {
369	        String firstName = normalizeHouseholdValue(owner.getFirstName());
370	        String lastName = normalizeHouseholdValue(owner.getLastName());
371	        int count = 0;
372	        for (Owner existing : ownerRepository.findAll()) {
373	            if (!existing.getId().equals(owner.getId())
374	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
375	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
376	                count++;
377	            }
378	        }
379	        return count;
380	    }
381	
382	    private static String normalizeEmail(String email) {
383	        return email == null ? null : email.toLowerCase(Locale.ROOT);
384	    }
385	
386	    /** Common street-type abbreviations expanded during address normalization. */
387	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
388	        "ST", "STREET",
389	        "RD", "ROAD",
390	        "AVE", "AVENUE");
391	
392	    /**
393	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
394	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
395	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
396	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
397	     * form.
398	     */
399	    private static String normalizeAddress(String address) {
400	        if (address == null) {
401	            return null;
402	        }
403	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
404	        if (collapsed.isEmpty()) {
405	            return "";
406	        }
407	        String[] tokens = collapsed.split(" ");
408	        StringBuilder sb = new StringBuilder(collapsed.length());
409	        for (int i = 0; i < tokens.length; i++) {
410	            if (i > 0) {
411	                sb.append(' ');
412	            }
413	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
414	        }
415	        return sb.toString();
416	    }
417	
418	    private static String normalizeTelephone(String telephone) {
419	        return telephone == null ? null : E164Telephone.toE164(telephone);
420	    }
421	
422	    /**
423	     * Rejects saving {@code owner} when its {@code normalized} telephone is already used by any
424	     * other owner, so no two owners can share a telephone number.
425	     *
426	     * @throws DuplicateTelephoneException if another owner already has the same normalized telephone
427	     */
428	    private void assertTelephoneUnique(Owner owner, String normalized) {
429	        if (normalized == null || normalized.isEmpty()) {
430	            return;
431	        }
432	        for (Owner existing : ownerRepository.findAll()) {
433	            if (!existing.getId().equals(owner.getId())
434	                    && normalized.equals(normalizeTelephone(existing.getTelephone()))) {
435	                throw new DuplicateTelephoneException(normalized);
436	            }
437	        }
438	    }
439	
440	    /**
441	     * Returns the existing owners that share both {@code lastName} (compared case-insensitively with
442	     * collapsed whitespace) and the normalized {@code address} with a new {@code owner} — i.e. the
443	     * members of the household it would join. Returns an empty list for an update to an existing
444	     * owner or when either household value is blank, so household rules only apply to genuine new
445	     * members.
446	     */
447	    private List<Owner> findHouseholdMembers(Owner owner) {
448	        if (!owner.isNew()) {
449	            return List.of();
450	        }
451	        String lastName = normalizeHouseholdValue(owner.getLastName());
452	        String address = normalizeHouseholdAddress(owner.getAddress());
453	        if (lastName.isEmpty() || address.isEmpty()) {
454	            return List.of();
455	        }
456	        List<Owner> household = new ArrayList<>();
457	        for (Owner existing : ownerRepository.findAll()) {
458	            if (!existing.getId().equals(owner.getId())
459	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))
460	                    && address.equals(normalizeHouseholdAddress(existing.getAddress()))) {
461	                household.add(existing);
462	            }
463	        }
464	        return household;
465	    }
466	
467	    /**
468	     * Pure guard: rejects creating {@code owner} when it would join a non-empty {@code household}
469	     * without acknowledging the shared household via {@link Owner#isSharesHousehold()}. Returns
470	     * without side effects otherwise.
471	     *
472	     * @throws DuplicateHouseholdException if another owner already lives at the same household and
473	     *                                     the request does not acknowledge the shared household
474	     */
475	    private void assertHouseholdAllowed(Owner owner, List<Owner> household) {
476	        if (!household.isEmpty() && !owner.isSharesHousehold()) {
477	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
478	        }
479	    }
480	
481	    /**
482	     * Assigns household membership when {@code owner} joins a non-empty {@code household}: the new
483	     * owner and every matching existing member that lacks one are given the same stable
484	     * {@code householdId}, and any updated existing members are persisted. No-op when the household
485	     * is empty.
486	     */
487	    private void assignHousehold(Owner owner, List<Owner> household) {
488	        if (household.isEmpty()) {
489	            return;
490	        }
491	        String householdId = resolveHouseholdId(owner, household);
492	        owner.setHouseholdId(householdId);
493	        for (Owner existing : household) {
494	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
495	                existing.setHouseholdId(householdId);
496	                ownerRepository.save(existing);
497	            }
498	        }
499	    }
500	
501	    /**
502	     * Returns the {@code householdId} shared by a household: the first non-blank identifier already
503	     * carried by an existing member, or otherwise a freshly derived stable identifier for the
504	     * joining {@code owner}'s normalized lastName and address.
505	     */
506	    private String resolveHouseholdId(Owner owner, List<Owner> household) {
507	        for (Owner existing : household) {
508	            if (existing.getHouseholdId() != null && !existing.getHouseholdId().isBlank()) {
509	                return existing.getHouseholdId();
510	            }
511	        }
512	        return generateHouseholdId(normalizeHouseholdValue(owner.getLastName()),
513	            normalizeHouseholdAddress(owner.getAddress()));
514	    }
515	
516	    /**
517	     * Derives a stable {@code householdId} formatted {@code 'HH-<12 upper-hex>'} from the SHA-256
518	     * digest of the normalized {@code lastName} and {@code address}, so all owners in the same
519	     * household deterministically share the same identifier.
520	     */
521	    private static String generateHouseholdId(String lastName, String address) {
522	        try {
523	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
524	            byte[] hash = digest.digest((lastName + "\u0000" + address).getBytes(StandardCharsets.UTF_8));
525	            StringBuilder sb = new StringBuilder();
526	            for (int i = 0; i < 6; i++) {
527	                sb.append(String.format("%02X", hash[i]));
528	            }
529	            return "HH-" + sb;
530	        } catch (NoSuchAlgorithmException e) {
531	            throw new IllegalStateException("SHA-256 not available", e);
532	        }
533	    }
534	
535	    /**
536	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
537	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
538	     */
539	    private static String normalizeHouseholdValue(String value) {
540	        if (value == null) {
541	            return "";
542	        }
543	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
544	    }
545	
546	    /**
547	     * Household comparison value for an address: the canonical {@link #normalizeAddress(String)}
548	     * form (never {@code null}), so duplicate detection and the shared household id compare
549	     * addresses using the same normalized representation that is stored and returned.
550	     */
551	    private static String normalizeHouseholdAddress(String address) {
552	        String normalized = normalizeAddress(address);
553	        return normalized == null ? "" : normalized;
554	    }
555	
